/* ---------- 等级体系 ---------- */
const LEVELS = [
  { key:"萌芽", need:0 },
  { key:"成长", need:30 },
  { key:"进阶", need:80 },
  { key:"小奥将", need:150 },
  { key:"奥数星", need:260 }
];

/* ---------- 由题目动态生成关卡地图 ---------- */
function buildChapters() {
  const map = {};
  QUESTIONS.forEach(q => {
    const key = "G" + q.grade;
    if (!map[key]) map[key] = { grade:q.grade, levels:[] };
  });
  const gradeName = {1:"一年级",2:"二年级",3:"三年级",4:"四年级",5:"五年级",6:"六年级"};
  const chapters = [];
  Object.keys(map).sort().forEach(k => {
    const g = map[k].grade;
    const levels = [];
    Object.keys(CATEGORIES).forEach(cat => {
      const qs = QUESTIONS.filter(q=>q.grade===g && q.cat===cat);
      if (qs.length) {
        levels.push({
          id: k+"_"+cat,
          grade:g, cat:cat, diff:qs[0].diff,
          title: CATEGORIES[cat].name + "闯关",
          questionIds: qs.map(q=>q.id)
        });
      }
    });
    chapters.push({ id:k, name:gradeName[g]+ " · 浅奥乐园", levels:levels });
  });
  return chapters;
}

/* 暴露到全局（经典脚本，非 module，保证 file:// 可直接运行） */
window.QIAO_DATA = { CATEGORIES, DIFF_NAME, KNOWLEDGE, QUESTIONS, BADGES, LEVELS, buildChapters };
